#!/usr/bin/env bash
# Copies the bd plugin (bydefaultstudio/bd-plugin) into this repo, so every Claude session loads it,
# including cloud sessions opened by another session, which never get the installed plugin.
# Usage: sync-bd-plugin.sh <bd-plugin checkout> <repo root>
# Run by .github/workflows/bd-plugin-sync.yml. Everything it writes is generated: edit bd-plugin, not the copy.
#   skills/<name>/      -> .claude/skills/bd:<name>/   (keeps the /bd:<name> command; a repo copy shadows the plugin's)
#   agents/*/*.md       -> .claude/agents/bd/
#   hooks/*.sh          -> .claude/bd/hooks/, wired into .claude/settings.json through .claude/bd/run-hook.sh,
#                          which skips them when the real plugin is loaded, so they never fire twice.
set -euo pipefail

src=$(cd "$1" && pwd)
repo=$(cd "$2" && pwd)
[ -f "$src/.claude-plugin/plugin.json" ] || { echo "Not a bd-plugin checkout: $src" >&2; exit 1; }
[ -d "$repo/.git" ] || { echo "Not a repo root: $repo" >&2; exit 1; }

skills="$repo/.claude/skills"
agents="$repo/.claude/agents/bd"
bd="$repo/.claude/bd"
settings="$repo/.claude/settings.json"

# Clear the previous copy (only paths this script owns).
find "$skills" -maxdepth 1 -type d -name 'bd:*' -exec rm -rf {} + 2>/dev/null || true
rm -rf "$agents" "$bd"
mkdir -p "$skills" "$agents" "$bd/hooks"

for d in "$src"/skills/*/; do
  n=$(basename "$d")
  cp -R "$d" "$skills/bd:$n"
done
find "$src/agents" -name '*.md' -exec cp {} "$agents/" \;
cp "$src"/hooks/*.sh "$bd/hooks/"
chmod +x "$bd"/hooks/*.sh

cat > "$bd/run-hook.sh" <<'HOOK'
#!/usr/bin/env bash
# Runs one of the copied bd plugin hooks, unless the real plugin is loaded (then it already runs its own).
p="$HOME/.claude/plugins"
ls -d "$p"/synced/*/bd >/dev/null 2>&1 && exit 0
jq -e '(.plugins["bd@bydefault"] // []) | length > 0' "$p/installed_plugins.json" >/dev/null 2>&1 && exit 0
exec bash "$(dirname "$0")/hooks/$1"
HOOK
chmod +x "$bd/run-hook.sh"

version=$(jq -r .version "$src/.claude-plugin/plugin.json")
commit=$(git -C "$src" rev-parse --short HEAD 2>/dev/null || echo unknown)
cat > "$bd/README.md" <<TXT
# bd plugin copy

Generated by \`.github/scripts/sync-bd-plugin.sh\` from bydefaultstudio/bd-plugin. Do not edit: change bd-plugin, release it, and the daily sync opens a pull request here.

version: $version
commit: $commit
TXT

# Wire the hooks into settings.json: drop old copies, add the plugin's current set.
[ -f "$settings" ] || echo '{}' > "$settings"
tmp=$(mktemp)
jq --slurpfile plugin "$src/hooks/hooks.json" '
  def ours: (.command // "") | test("\\.claude/bd/run-hook\\.sh");
  .hooks = (.hooks // {})
  | .hooks |= with_entries(.value |= (map(.hooks |= map(select(ours | not))) | map(select(.hooks | length > 0))))
  | reduce ($plugin[0].hooks | to_entries[]) as $e (.;
      .hooks[$e.key] = ((.hooks[$e.key] // []) + ($e.value | map(.hooks |= map(
        .command |= sub("^\"\\$\\{CLAUDE_PLUGIN_ROOT\\}\"/hooks/(?<f>[^ ]+)$"; "bash \"$CLAUDE_PROJECT_DIR/.claude/bd/run-hook.sh\" \(.f)")
      )))))
  | .hooks |= with_entries(select(.value | length > 0))
' "$settings" > "$tmp"
mv "$tmp" "$settings"

echo "Synced bd plugin $version ($commit)"
